--   joseito-mateo [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Tamárez Mateo, known as Joseíto Mateo and called the King of Merengue, was a Dominican singer. He began performing in the nineteen-thirties and was still working at the end of his life, which gave him a career of more than seventy years and made him the longest continuous presence in Dominican popular music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Santo Domingo and Havana","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born in Santo Domingo in 1920 and started singing as a young man, building an audience through the thirties and forties. On one of his trips to Cuba he stayed on to sing at CMQ, then the largest station on the island, alongside Celia Cruz and the Sonora Matancera, at the point when Cuban radio was setting the terms for the whole Caribbean.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Gran Combo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"After the killing of Trujillo in 1961 he went to try his luck in Puerto Rico, and in 1962 he sang with El Gran Combo on the group’s first tour to Panama, promoting the album El Gran Combo con Joseíto Mateo. He adapted to their repertoire, singing plena, bomba, guaracha and bolero, and it was on that trip that he met the young Pellín Rodríguez and Andy Montañez, who took his place in the band.","type":"text"}]},{"type":"paragraph","content":[{"text":"He gave a plain reason for leaving. He had to go back to Santo Domingo to clear his name: in the years after the dictatorship anyone who had worked under it was being pursued, and he was being called a spy at home while he was singing abroad.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songs","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His catalogue is enormous and began early. King of Merengue! appeared in 1950 and Merenchanga Pa’ la Pachanga in 1956, and through the sixties he released album after album — El Verdadero Rey del Merengue in 1964, Caña Brava Vol. 3 and Merengues Vol. 2 in 1966, Salsa Explosiva in 1970.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songs that stayed are Madame Chuchí, Dame la Visa, La Cotorra de Rosa, La Patrulla, Juanita Morel and Merenguero Hasta la Tambora. In 1979 he made an album of merengues with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dab6636c-21fd-4e34-a0a2-e59e9e147bbd","displayText":"Luis Kalaff","occurrenceId":"a6d3b2a2-2617-4e18-a755-38395aa53c8f"}},{"text":", whose Cuando Yo Me Muera he had also recorded.","type":"text"}]},{"type":"paragraph","content":[{"text":"The dancing","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"What separated him was not only the voice. He sang while dancing, and the way he moved on stage became part of what merengue looked like as well as what it sounded like, at a moment when the genre was moving from country ensembles into ballrooms and television studios.","type":"text"}]},{"type":"paragraph","content":[{"text":"The honours","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Acroarte gave him the Gran Soberano, its highest award, in 2004, and on 11 November 2010 the Latin Recording Academy presented him with its Musical Excellence Award for his contribution to Latin music.","type":"text"}]},{"type":"paragraph","content":[{"text":"He died in 2018, at ninety-eight. At his wake ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"6a5a5bcc-0754-4f41-b420-258fec9c6a1d"}},{"text":" said that Joseíto had been the greatest because everything the rest of them did was copied from him, and that he would never really be dead for the country.","type":"text"}]}]}'::jsonb WHERE id = '5e639bfa-a309-4323-af22-4b306db16e74';
--   joseito-mateo [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Tamárez Mateo, conocido como Joseíto Mateo y llamado El Rey del Merengue, fue un cantante dominicano. Empezó a presentarse en los años treinta y seguía trabajando al final de su vida, lo que le dio una carrera de más de setenta años y lo convirtió en la presencia continua más larga de la música popular dominicana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Santo Domingo y La Habana","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació en Santo Domingo en 1920 y empezó a cantar de joven, ganando público a lo largo de los treinta y los cuarenta. En uno de sus viajes a Cuba se quedó a cantar en la CMQ, entonces la emisora más grande de la isla, junto a Celia Cruz y la Sonora Matancera, justo cuando la radio cubana fijaba las reglas para todo el Caribe.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Gran Combo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tras el ajusticiamiento de Trujillo en 1961 se fue a probar suerte a Puerto Rico, y en 1962 cantó con El Gran Combo en la primera gira del grupo a Panamá, promocionando el disco El Gran Combo con Joseíto Mateo. Se adaptó a su repertorio, cantando plena, bomba, guaracha y bolero, y en ese viaje conoció a los jóvenes Pellín Rodríguez y Andy Montañez, que terminaron ocupando su lugar en la orquesta.","type":"text"}]},{"type":"paragraph","content":[{"text":"La razón de su salida la dio él mismo sin rodeos. Tuvo que volver a Santo Domingo a limpiar su nombre: en los años posteriores a la dictadura se perseguía a quien hubiera trabajado bajo ella, y mientras él cantaba afuera en el país lo llamaban espía.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las canciones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su catálogo es enorme y empezó temprano. King of Merengue! salió en 1950 y Merenchanga Pa’ la Pachanga en 1956, y a lo largo de los sesenta publicó disco tras disco: El Verdadero Rey del Merengue en 1964, Caña Brava Vol. 3 y Merengues Vol. 2 en 1966, Salsa Explosiva en 1970.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las canciones que quedaron son Madame Chuchí, Dame la Visa, La Cotorra de Rosa, La Patrulla, Juanita Morel y Merenguero Hasta la Tambora. En 1979 hizo un disco de merengues con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dab6636c-21fd-4e34-a0a2-e59e9e147bbd","displayText":"Luis Kalaff","occurrenceId":"1f023583-ad08-4f83-a554-c5022288530c"}},{"text":", de quien además había grabado Cuando Yo Me Muera.","type":"text"}]},{"type":"paragraph","content":[{"text":"El baile","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Lo que lo separaba no era solo la voz. Cantaba bailando, y su manera de moverse en tarima pasó a formar parte de cómo se veía el merengue y no solo de cómo sonaba, justo cuando el género salía de los conjuntos de campo hacia los salones de baile y los estudios de televisión.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los reconocimientos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Acroarte le dio el Gran Soberano, su máximo galardón, en 2004, y el 11 de noviembre de 2010 la Academia Latina de la Grabación le entregó el Premio a la Excelencia Musical por su aporte a la música latina.","type":"text"}]},{"type":"paragraph","content":[{"text":"Murió en 2018, a los noventa y ocho años. En su velatorio ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"05db25ef-26b3-40d2-bea7-6030ff74d410"}},{"text":" dijo que Joseíto había sido el más grande porque de él lo copiaron todo los demás, y que para el país no iba a morirse nunca.","type":"text"}]}]}'::jsonb WHERE id = '6413dd84-18bc-46a6-9a91-ef98a9fe5fea';
--   peter-cruz [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Peter Cruz, born Pedro Antonio de la Cruz in Yamasá, is a Dominican merengue singer. He was inside three of the most important bands of the nineteen-eighties and he is one of the founders of a fourth, and for most of that time his name was the smallest thing on the sleeve.","type":"text"}]},{"type":"paragraph","content":[{"text":"Coming up through the bands","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Yamasá is a town in Monte Plata, inland and unglamorous, and he left it for the orchestras. He sang with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"c4dcb614-98cd-4fe6-b95b-6544b45e558d"}},{"text":" and with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f050869b-f4c0-4281-b883-bce0120ad9b2","displayText":"Aníbal Bravo","occurrenceId":"c69347c7-b0c0-4d4c-9f63-918aef4e587f"}},{"text":" before the job that made him, which was with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"5280248a-19b6-4920-886f-811bfa0e1cd8"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Ron Pa To El Mundo, from 1984, is billed to Peter Cruz with Wilfrido Vargas’s orchestra. Being the voice on a Wilfrido record in that decade meant being heard across the whole Caribbean, and it also meant being interchangeable: the band was the name, the singer was staff.","type":"text"}]},{"type":"paragraph","content":[{"text":"He has said publicly that Wilfrido Vargas never mentions him in interviews. Whether that is an oversight or something else, the omission is real enough that he has been asked about it on camera, and it is a fair description of what happens to a singer who was hired rather than billed.","type":"text"}]},{"type":"paragraph","content":[{"text":"Founding the Internacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He tells it that he founded the Orquesta Internacional together with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando","occurrenceId":"c6c87b9a-e90b-47ac-abad-cfda30cc2e69"}},{"text":" and Carlos Herrera. The band went on to be one of the defining merengue orchestras of its era and it carries Ramón Orlando’s name to this day.","type":"text"}]},{"type":"paragraph","content":[{"text":"He left it at the top, and his account of why is a promise that was not kept. He does not say more than that in public, and the detail stays where he left it.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cometa Blanca","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cometa Blanca is the record he is attached to, and his account of where it came from is the best thing in his story: he found it on a cassette by Chiquetete, a Spanish flamenco and copla singer, and brought it to the band.","type":"text"}]},{"type":"paragraph","content":[{"text":"A merengue orchestra taking a song off an Andalusian record is not an odd thing in itself — Dominican bands have always eaten whatever was in the room — but it takes somebody actually listening to hear a merengue inside a copla. He also says the mambo, the horn break that lifts the song, was a change he made to the arrangement himself.","type":"text"}]},{"type":"paragraph","content":[{"text":"That is an arranging credit claimed forty years later by the man who sang it. The singer usually gets the applause and never the credit, and a singer who finally asks for the credit is doing something the trade rarely allows.","type":"text"}]},{"type":"paragraph","content":[{"text":"On his own","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"After the Internacional he put out Peter Cruz y su Banda in 1986 and went on working. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"04fde466-8488-43b4-ab52-e07d12791141","displayText":"Fénix Ortiz","occurrenceId":"de5693dd-2cdd-4a62-897c-1f5cf589ad8f"}},{"text":" sang on his records. He has since turned up on a Wilfrido Vargas record alongside ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"258012ee-5290-4038-a79f-e60101627a4b"}},{"text":" and Junior Castillo — three voices from three different bands of the same decade, on one track.","type":"text"}]},{"type":"paragraph","content":[{"text":"He still gives interviews, at length, and the interest in them is not nostalgia. He is one of the few people left who can say what actually happened inside those orchestras, and he is willing to say it.","type":"text"}]}]}'::jsonb WHERE id = '62300e59-1cb5-43c3-8be7-2611bd9aadbe';
--   peter-cruz [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Peter Cruz, de nombre Pedro Antonio de la Cruz, de Yamasá, es cantante de merengue dominicano. Estuvo dentro de tres de las bandas más importantes de los ochenta y es fundador de una cuarta, y durante casi todo ese tiempo su nombre fue lo más pequeño de la carátula.","type":"text"}]},{"type":"paragraph","content":[{"text":"Subir por las orquestas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Yamasá es un pueblo de Monte Plata, tierra adentro y sin glamour, y él lo dejó por las orquestas. Cantó con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"e27e073e-4dae-4d95-ab92-2d86db517d40"}},{"text":" y con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f050869b-f4c0-4281-b883-bce0120ad9b2","displayText":"Aníbal Bravo","occurrenceId":"59b1bb9c-46ec-4b73-86e4-2928f8f58b9d"}},{"text":" antes del trabajo que le hizo el nombre, que fue con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"44230d0a-8352-4b2f-a223-9df7d2f03c69"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Ron Pa To El Mundo, de 1984, va acreditada a Peter Cruz con la orquesta de Wilfrido Vargas. Ser la voz de un disco de Wilfrido en esa década quería decir que te oía el Caribe entero, y quería decir también que eras intercambiable: la banda era el nombre, el cantante era personal contratado.","type":"text"}]},{"type":"paragraph","content":[{"text":"Él ha dicho en público que Wilfrido Vargas nunca lo menciona en sus entrevistas. Sea descuido o sea otra cosa, la omisión es lo bastante real como para que se lo hayan preguntado frente a una cámara, y describe bien lo que le pasa a un cantante al que se contrata en vez de anunciarlo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fundar la Internacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Él cuenta que fundó la Orquesta Internacional junto a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando","occurrenceId":"319bc944-a9ff-42a8-9c56-eae5a445ea48"}},{"text":" y Carlos Herrera. La banda terminó siendo una de las orquestas de merengue que definieron su época y hasta hoy lleva el nombre de Ramón Orlando.","type":"text"}]},{"type":"paragraph","content":[{"text":"Se fue de ella en lo más alto, y su versión de por qué es una promesa que no se cumplió. En público no dice más que eso, y el detalle se queda donde él lo dejó.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cometa Blanca","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cometa Blanca es el disco al que está pegado, y su relato de dónde salió es lo mejor de su historia: la encontró en un casete de Chiquetete, cantante español de flamenco y copla, y se la llevó a la banda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Que una orquesta de merengue agarre una canción de un disco andaluz no es raro en sí —las bandas dominicanas siempre se han comido lo que hubiera en el cuarto—, pero hace falta alguien oyendo de verdad para oír un merengue dentro de una copla. Dice además que el mambo, el corte de metales que levanta el tema, fue un cambio que él le hizo al arreglo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Es un crédito de arreglo reclamado cuarenta años después por el que lo cantó. Al cantante le suelen dar los aplausos y nunca el crédito, y un cantante que por fin lo reclama está haciendo algo que el oficio rara vez permite.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por su cuenta","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Después de la Internacional sacó Peter Cruz y su Banda en 1986 y siguió trabajando. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"04fde466-8488-43b4-ab52-e07d12791141","displayText":"Fénix Ortiz","occurrenceId":"38e8290e-732f-44a4-9d8d-1a73014029b5"}},{"text":" cantó en sus discos. Después ha aparecido en un tema de Wilfrido Vargas junto a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"a0d79fdf-3d40-4fb0-bf5e-d247a60fb839"}},{"text":" y Junior Castillo: tres voces de tres bandas distintas de la misma década, en un solo corte.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sigue dando entrevistas, largas, y el interés que tienen no es la nostalgia. Es de las pocas personas que quedan capaces de contar lo que de verdad pasaba dentro de aquellas orquestas, y está dispuesto a contarlo.","type":"text"}]}]}'::jsonb WHERE id = 'aa456ca4-c0a5-4171-a646-73f3315dea5e';
--   pochy-y-su-cocoband [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Pochy y su Cocoband is a Dominican merengue orchestra founded and led by Pochy Familia, who writes and arranges everything it records. Between the end of the eighties and the middle of the nineties it put out an unbroken run of hits that no other Dominican merengue band has matched, and it is still filling rooms four decades on.","type":"text"}]},{"type":"paragraph","content":[{"text":"Before the band","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Pochy Familia was writing before he was leading. His first hit, La Negra Pola, was written in 1979 for ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"10d5bbf2-9760-4a19-84ae-34bdd3664f43"}},{"text":" — nearly a decade before the Cocoband existed — and it won him a gold record while he was still very young.","type":"text"}]},{"type":"paragraph","content":[{"text":"He spent the years that followed as an arranger and composer for other people’s orchestras, among them ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3422883e-7048-48af-bb03-c68c8c557ee4","displayText":"Los Hermanos Rosario","occurrenceId":"b482f963-a331-4530-a26f-bda6a6031cf3"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4361e223-5102-4fee-be4a-05bea6281807","displayText":"Richie Ricardo","occurrenceId":"b9adcac5-b284-46a5-900d-513278ec4769"}},{"text":", and worked in the studios of Mateo San Martín and his label Kubaney. That is where the band came from: not from a stage, but from the arranging desk.","type":"text"}]},{"type":"paragraph","content":[{"text":"The founding","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He put the Cocoband together in 1988 with other musicians and singers, and what followed is the statistic the genre still quotes. From 1988 to 1995 the group placed close to seventy hits without a break, and across seventeen productions it has more than a hundred. Every single track on the first seven records charted, from the opening cut to the last one.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pero con coco","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The sound is güira, tambora and a horn line pushed hard, with lyrics that are funny before they are anything else. Salsa con Coco, La Faldita, La Flaca, El Ombliguito, A Usted Lo Botan, Bala Bala, Los Hombres Feos, Ya Se Me Olvidó Tu Nombre, El Hombre Llegó Parao, De Reversa, La Pinea, Ay Pero Qué Calor, El Cacú, Esperando el 31, El Batecito and La Peliona are the ones the country knows.","type":"text"}]},{"type":"paragraph","content":[{"text":"The band also kept material back. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dc89c826-c298-48c8-aa05-50e77d85264a","displayText":"Los Kenton","occurrenceId":"a4f47170-6f7c-4efe-b2c7-c051cdc0615b"}},{"text":" asked them to release El Negro del Swing, which the Cocoband had shelved, and had a hit with it.","type":"text"}]},{"type":"paragraph","content":[{"text":"Their audience has a name of its own. Cocoband followers call themselves the Cocotuses.","type":"text"}]},{"type":"paragraph","content":[{"text":"35 Años con Coco","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In October 2022 sixteen merengue singers recorded a single song together in tribute to the band, running through sixteen of its hits — all of them written by Pochy Familia. Listín Diario reported it as the first time in Dominican musical history that that many recognised artists of the genre had joined voices to honour one merenguero.","type":"text"}]},{"type":"paragraph","content":[{"text":"Those who sang on it were ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"d3e516e8-a430-4438-8800-3af13dd99d29"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02b306b3-acc0-4800-b314-05683205d1c5","displayText":"Jossie Esteban y La Patrulla 15","occurrenceId":"1942daec-f9d8-4a6f-8d10-ab971e790536"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"070e7449-814e-4ea6-a009-7a091b7e4878","displayText":"Milly Quezada","occurrenceId":"b0982b41-4a37-4dd1-8091-d6e17f70eafa"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"1ca8f31f-5481-43c7-b4a5-745e2eaca498"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"df8fb71a-7482-4cfa-bf65-b9e6834ce125"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc2289d0-ae94-48b5-8eb9-7f0ae18b845a","displayText":"Miriam Cruz","occurrenceId":"aefc36e9-7aff-4ca7-b74a-600e5a8a3f38"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fc762d4-96b8-4ecf-aca8-fdf52936658e","displayText":"Toño Rosario","occurrenceId":"8dbd2419-d6a5-47de-99c6-24b374030fba"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta “El Torito”","occurrenceId":"e1a6bfd8-9298-4fa2-820c-c49b6e797294"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"1b5fbc40-1981-4918-b141-9bbcfced3e24"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fb033f0-4f8b-4101-a67d-1d445f316dc4","displayText":"Rafa Rosario","occurrenceId":"d5863979-6f73-4f5c-8d19-afcaa8f63755"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"b41d4bd2-9303-4834-885e-e7dee35a0287","displayText":"José Peña Suazo y La Banda Gorda","occurrenceId":"c21936f6-ec38-407c-93a7-68e4b35e02d5"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c73737c2-0106-4a87-8dbe-5f1650d34342","displayText":"Kinito Méndez","occurrenceId":"e84c5062-2bf9-453c-9cb6-bf95eccb814a"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"71b3ae39-874b-4849-b975-b234bcf7a472"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"c751c11c-59c7-42ab-91f2-7abd82ddf01c"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"acb54568-08b4-4f5b-a6b8-5f50f33dfcbe","displayText":"Jandy Ventura","occurrenceId":"c3be4548-000a-4256-a6df-37c0d66a173c"}},{"text":", along with Chucky Acosta. The anniversary concert followed that December at the Teatro La Fiesta of the Hotel Jaragua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Four decades","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The band has not stopped. Las Mujeres Siempre Ganan came in 2021, Pa’ los Coquitos in 2026, and its 2026 calendar runs through the Hotel Jaragua, the Gran Arena del Cibao, the Gran Teatro Nacional, the amphitheatre at Altos de Chavón and the Hard Rock in Santo Domingo.","type":"text"}]}]}'::jsonb WHERE id = '9e5910cb-6a8c-45ac-999c-0ca1a0c75eff';
--   pochy-y-su-cocoband [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Pochy y su Cocoband es una orquesta de merengue dominicana fundada y dirigida por Pochy Familia, que escribe y arregla todo lo que graba. Entre finales de los ochenta y mediados de los noventa sacó una racha ininterrumpida de éxitos que ninguna otra banda de merengue dominicana ha igualado, y sigue llenando salas cuatro décadas después.","type":"text"}]},{"type":"paragraph","content":[{"text":"Antes de la banda","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Pochy Familia escribía antes de dirigir. Su primer éxito, La Negra Pola, lo escribió en 1979 para ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"285c3d11-a355-4f76-81db-dd26c7654318"}},{"text":" —casi una década antes de que existiera la Cocoband— y le valió un disco de oro siendo muy joven.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los años siguientes los pasó como arreglista y compositor de orquestas ajenas, entre ellas ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3422883e-7048-48af-bb03-c68c8c557ee4","displayText":"Los Hermanos Rosario","occurrenceId":"118b9234-ce22-4635-8bb9-f2b4a99d998d"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4361e223-5102-4fee-be4a-05bea6281807","displayText":"Richie Ricardo","occurrenceId":"8d580451-3e58-47ee-88c5-ddeb2128efb7"}},{"text":", y trabajó en los estudios de Mateo San Martín y su disquera Kubaney. De ahí salió la banda: no de una tarima, sino de la mesa de arreglos.","type":"text"}]},{"type":"paragraph","content":[{"text":"La fundación","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Armó la Cocoband en 1988 junto a otros músicos y cantantes, y lo que vino después es la estadística que el género todavía cita. De 1988 a 1995 el grupo colocó cerca de setenta éxitos sin interrupción, y en diecisiete producciones lleva más de cien. De los siete primeros discos pegaron todas las canciones, de la primera a la última.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pero con coco","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El sonido es güira, tambora y una línea de metales empujada fuerte, con letras que son graciosas antes que ninguna otra cosa. Salsa con Coco, La Faldita, La Flaca, El Ombliguito, A Usted Lo Botan, Bala Bala, Los Hombres Feos, Ya Se Me Olvidó Tu Nombre, El Hombre Llegó Parao, De Reversa, La Pinea, Ay Pero Qué Calor, El Cacú, Esperando el 31, El Batecito y La Peliona son las que el país se sabe.","type":"text"}]},{"type":"paragraph","content":[{"text":"La banda guardaba material además. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dc89c826-c298-48c8-aa05-50e77d85264a","displayText":"Los Kenton","occurrenceId":"819506a0-2cef-44a9-bf1f-484d19b6bf7c"}},{"text":" les pidió que liberaran El Negro del Swing, que la Cocoband tenía engavetado, y pegaron con ella.","type":"text"}]},{"type":"paragraph","content":[{"text":"Su público tiene nombre propio. Los seguidores de la Cocoband se llaman a sí mismos los Cocotuses.","type":"text"}]},{"type":"paragraph","content":[{"text":"35 Años con Coco","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En octubre de 2022 dieciséis cantantes de merengue grabaron juntos una sola canción en homenaje a la banda, recorriendo dieciséis de sus éxitos, todos de la autoría de Pochy Familia. Listín Diario lo reportó como la primera vez en la historia musical dominicana que tantos artistas reconocidos del género unen sus voces para homenajear a un merenguero.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cantaron en ella ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"a55cf1cc-9fb6-4804-ae5a-e98789fee4f9"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02b306b3-acc0-4800-b314-05683205d1c5","displayText":"Jossie Esteban y La Patrulla 15","occurrenceId":"77aa52ed-ee5e-4c1a-aef8-2fe9e91150e0"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"070e7449-814e-4ea6-a009-7a091b7e4878","displayText":"Milly Quezada","occurrenceId":"7bf28248-aff3-42c7-bd1f-1b23e2b5391b"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"722810aa-0bcd-4f88-b3e9-6b0dbbaec60e"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"531b5dde-8aba-44e2-8ae0-78cf5bad61f0"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc2289d0-ae94-48b5-8eb9-7f0ae18b845a","displayText":"Miriam Cruz","occurrenceId":"696a4515-8fa2-4f82-bfd5-4f8ad161533a"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fc762d4-96b8-4ecf-aca8-fdf52936658e","displayText":"Toño Rosario","occurrenceId":"c46fdcb0-e04b-413e-856d-da9f561f37a5"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta “El Torito”","occurrenceId":"dcbff506-26cc-4e29-a9ec-4705b03bf11e"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"b2804223-7d1a-48bd-ae75-efe2ec0ae091"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fb033f0-4f8b-4101-a67d-1d445f316dc4","displayText":"Rafa Rosario","occurrenceId":"08f89993-f24d-4af8-9c15-954e0aa19013"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"b41d4bd2-9303-4834-885e-e7dee35a0287","displayText":"José Peña Suazo y La Banda Gorda","occurrenceId":"24afe8d2-055c-43e2-8a1b-f4932b514228"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c73737c2-0106-4a87-8dbe-5f1650d34342","displayText":"Kinito Méndez","occurrenceId":"da58aa3a-0fee-4f28-afea-96d76779b0de"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"da41d174-5a5e-42dc-af2e-3492ebecc648"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"462a58fd-76fa-4fa2-a814-db5e7b7a81e3"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"acb54568-08b4-4f5b-a6b8-5f50f33dfcbe","displayText":"Jandy Ventura","occurrenceId":"ba82dd4c-fd68-4f92-b158-7106b6d1f451"}},{"text":", además de Chucky Acosta. El concierto de aniversario vino ese diciembre en el Teatro La Fiesta del Hotel Jaragua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cuatro décadas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"La banda no ha parado. Las Mujeres Siempre Ganan salió en 2021, Pa’ los Coquitos en 2026, y su calendario de 2026 recorre el Hotel Jaragua, la Gran Arena del Cibao, el Gran Teatro Nacional, el anfiteatro de Altos de Chavón y el Hard Rock de Santo Domingo.","type":"text"}]}]}'::jsonb WHERE id = 'b75a00be-aaf1-4ad4-94ac-4c5466a4182e';
--   yoskar-sarante [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Yoskar Sarante Ventura, known as El Prabú, was a Dominican bachata singer. He had a high, unforced voice that could hold a line without pushing it, and for a stretch at the start of the century he was one of the two most heard bachateros in the country.","type":"text"}]},{"type":"paragraph","content":[{"text":"Villas Agrícolas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born in 1970 in Villas Agrícolas, a barrio of Santo Domingo. As a boy he sang in parks and public squares while his older brother played guitar, and what they collected went to the household. He entered the children’s singing contests on Dominican television, among them Mundo Infantil, and later enrolled at the Iris del Valle music school in Los Mina, paying for it with work on building sites.","type":"text"}]},{"type":"paragraph","content":[{"text":"The merengue orchestras","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His professional career began in merengue rather than bachata. He sang with Grupo Internacional Melao, and after finishing at the music school passed through the orchestras of Tomás Barrera, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"af0b240c-234b-4214-ab00-2d41575ba01d"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e5129444-0923-4e06-b77d-f82f14c02b7d","displayText":"Aramis Camilo","occurrenceId":"d8487513-f171-4f98-8f66-6a3bb8dccee5"}},{"text":" and Guancho Viloria. The years in front of merengue bands gave him the breath control and the projection that later separated him inside a slower genre.","type":"text"}]},{"type":"paragraph","content":[{"text":"Llora Alma Mía","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He turned to bachata and released El Prabú in 1994, the record that gave him his name, followed by Niña Sedienta in 1996 and Si Fuera Ella in 1998. The album that made him was Llora Alma Mía, in 2000: La Noche, No Te Detengas, Si Te Llego a Perder and the title song are all still standards of the genre.","type":"text"}]},{"type":"paragraph","content":[{"text":"No Es Casualidad followed in 2002 and Viví in 2004. Between those records he and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e566c763-02c1-4f96-8a82-edbba9fc0bb2","displayText":"Elvis Martínez","occurrenceId":"c9aaff5f-8de7-40f2-9bf3-1effe4ae92fa"}},{"text":" were the two bachateros the country listened to most, at the moment when bachata was finishing its move from the margins to the centre of Dominican radio. He was invited to New York and sang at the Mets stadium in front of the city’s mayor, which opened the United States to him.","type":"text"}]},{"type":"paragraph","content":[{"text":"The later records","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Parada 37 came in 2006 and Vuelve Vuelve in 2008, and he kept releasing into the following decade. The songs that stayed are the slow ones: Vas a Llorar, Guitarra, Por una Mentira, Perdido, Perdóname, No Tengo Suerte en el Amor, El Amor es Libre, He Tenido que Llorar and Guerra de Amor.","type":"text"}]},{"type":"paragraph","content":[{"text":"He also recorded within the wider revival of the genre, appearing on collections such as Bachata Típico and The Rough Guide to Bachata, which carried Dominican bachata to listeners who had come to it from outside. He died in a hospital in Orlando, Florida, on 28 January 2019.","type":"text"}]}]}'::jsonb WHERE id = 'd34f14f9-4fde-4abb-b3f2-53e9e88e8bba';
--   yoskar-sarante [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Yoskar Sarante Ventura, conocido como El Prabú, fue un cantante de bachata dominicano. Tenía una voz aguda y sin esfuerzo, capaz de sostener una frase sin forzarla, y durante un tramo de principios de siglo fue uno de los dos bachateros más escuchados del país.","type":"text"}]},{"type":"paragraph","content":[{"text":"Villas Agrícolas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació en 1970 en Villas Agrícolas, barrio de Santo Domingo. De niño cantaba en parques y plazas públicas mientras su hermano mayor tocaba la guitarra, y lo que recogían iba al sustento de la casa. Concursó en los programas infantiles de canto de la televisión dominicana, entre ellos Mundo Infantil, y más adelante se inscribió en la Escuela de Música Iris del Valle, en Los Mina, que pagó trabajando en construcción.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las orquestas de merengue","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su carrera profesional empezó en el merengue y no en la bachata. Cantó con el Grupo Internacional Melao y, al graduarse de la escuela de música, pasó por las orquestas de Tomás Barrera, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73691e65-206a-4c71-9b5f-8689f15b2584","displayText":"Cheché Abreu","occurrenceId":"f8f3ac2c-c5c3-4458-936b-0e1662cf14ff"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e5129444-0923-4e06-b77d-f82f14c02b7d","displayText":"Aramis Camilo","occurrenceId":"c7a5a8da-62ad-40a9-920d-7cfe4a6c8f97"}},{"text":" y Guancho Viloria. Los años delante de bandas de merengue le dieron el aire y la proyección que después lo distinguieron dentro de un género más lento.","type":"text"}]},{"type":"paragraph","content":[{"text":"Llora Alma Mía","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Se pasó a la bachata y sacó El Prabú en 1994, el disco que le dio el nombre, seguido de Niña Sedienta en 1996 y Si Fuera Ella en 1998. El álbum que lo hizo fue Llora Alma Mía, de 2000: La Noche, No Te Detengas, Si Te Llego a Perder y el tema que le da título siguen siendo clásicos del género.","type":"text"}]},{"type":"paragraph","content":[{"text":"Detrás vinieron No Es Casualidad en 2002 y Viví en 2004. Entre esos discos, él y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e566c763-02c1-4f96-8a82-edbba9fc0bb2","displayText":"Elvis Martínez","occurrenceId":"f800fb22-df05-4b83-b2f2-2d5837b5b407"}},{"text":" eran los dos bachateros que más oía el país, justo cuando la bachata terminaba de pasar del margen al centro de la radio dominicana. Lo invitaron a Nueva York y cantó en el estadio de los Mets delante del alcalde de la ciudad, lo que le abrió Estados Unidos.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los discos siguientes","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Parada 37 salió en 2006 y Vuelve Vuelve en 2008, y siguió publicando en la década siguiente. Las canciones que quedaron son las lentas: Vas a Llorar, Guitarra, Por una Mentira, Perdido, Perdóname, No Tengo Suerte en el Amor, El Amor es Libre, He Tenido que Llorar y Guerra de Amor.","type":"text"}]},{"type":"paragraph","content":[{"text":"Grabó también dentro del rescate más amplio del género, apareciendo en recopilaciones como Bachata Típico y The Rough Guide to Bachata, que llevaron la bachata dominicana a oyentes que llegaron a ella desde afuera. Murió en un hospital de Orlando, Florida, el 28 de enero de 2019.","type":"text"}]}]}'::jsonb WHERE id = 'f02ec419-088b-4761-b3a8-895cdb821860';

-- rene-del-risco-bermudez: "René del Risco Bermudez" -> "René del Risco Bermúdez"
UPDATE artists SET name = 'René del Risco Bermúdez' WHERE slug = 'rene-del-risco-bermudez';
--   fernando-casado [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Fernando Casado, billed as El Magistrado, is a Dominican singer, broadcaster, actor and music researcher. He built a career on a velvet bolero voice and then spent much of it on something less commercial: putting the criolla, a Dominican song form that had gone quiet, back into the country’s working repertoire.","type":"text"}]},{"type":"paragraph","content":[{"text":"The voice and the microphone","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born on 4 March in San José de Ocoa and raised in the capital. He studied singing with the maestro Charles Guild and made his first appearances on live radio, and then did what a young man with that voice did in the fifties: he became an announcer.","type":"text"}]},{"type":"paragraph","content":[{"text":"He read news on a Spanish-language station in New York and worked through most of the Dominican dial, ending as head of the announcers’ department and programming coordinator at La Voz Dominicana, and later directing two other stations. He then moved to television and kept a programme under his own name across three different channels, one of which he founded.","type":"text"}]},{"type":"paragraph","content":[{"text":"That double career matters for what came later. A singer who also controls a microphone and a schedule can put a repertoire on the air, and he did.","type":"text"}]},{"type":"paragraph","content":[{"text":"The criolla","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The criolla is the Dominican romantic song of the nineteenth century, the music of trovadores like Raudo Saldaña and Antonio Mesa, and by the middle of the twentieth it was more or less a museum piece. He recorded Cartas y Lágrimas, Aquel Beso, Carmencita and Duvergé, and he kept singing them when nothing about the market rewarded it.","type":"text"}]},{"type":"paragraph","content":[{"text":"He also worked as a researcher and writer, which is unusual for a performer and is the reason the recovery stuck. He was arguing a case about what Dominican music includes — merengue and bolero, but also the criolla, the son and the palos — and Juan Luis Guerra wrote about that argument at length last year.","type":"text"}]},{"type":"paragraph","content":[{"text":"The strangest thing in his discography belongs here too: a duet with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ec0423fc-fe53-42e9-8d0f-f2ae902512d3","displayText":"Eduardo Brito","occurrenceId":"e91cfa17-4dbd-4733-a08f-a47e703d62c0"}},{"text":". Brito died in 1946, so it was assembled by technical means rather than sung together, and it is exactly the gesture of a man who thinks the nineteenth-century repertoire is still live material.","type":"text"}]},{"type":"paragraph","content":[{"text":"Festivals and the rest","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He represented the country at the OTI song festival in Spain in 1972 with Siempre Habrá Una Sonrisa En La Luna, and took second place at the same festival in 1977 with Al Nacer Cada Enero. He has sung at Carnegie Hall and appeared on the big Spanish-language variety programmes of the era, in Chile, in Spain and on the Mexican show that filmed an edition in La Romana.","type":"text"}]},{"type":"paragraph","content":[{"text":"His repertoire runs through the good Dominican songwriting of the period. He recorded Una Primavera Para El Mundo, on a poem by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c1575281-d275-4f34-a721-9f02736132d2","displayText":"René del Risco Bermúdez","occurrenceId":"081e3324-b964-40de-93e8-21fc5cc388dd"}},{"text":", and Por Amor by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ba42e200-51b0-437b-99ac-1daf39ade337","displayText":"Rafael Solano","occurrenceId":"89dc8541-24f7-4316-b963-b0de889cd913"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"The Ayuntamiento of the Distrito Nacional named him a distinguished citizen, and he was later chosen for the country’s musical reserve. He is still working, still being interviewed at home, and still making the same argument about the criolla.","type":"text"}]}]}'::jsonb WHERE id = 'a9f9a94e-e684-4902-9aa6-c57af3d15646';
--   fernando-casado [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Fernando Casado, anunciado como El Magistrado, es cantante, locutor, actor e investigador musical dominicano. Levantó una carrera sobre una voz aterciopelada de bolerista y después dedicó buena parte de ella a algo bastante menos comercial: devolverle a la criolla, una forma dominicana que se había apagado, un sitio en el repertorio vivo del país.","type":"text"}]},{"type":"paragraph","content":[{"text":"La voz y el micrófono","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació un 4 de marzo en San José de Ocoa y se crió en la capital. Estudió canto con el maestro Charles Guild e hizo sus primeras interpretaciones en programas de radio en vivo, y después hizo lo que hacía en los años cincuenta un muchacho con esa voz: se metió a locutor.","type":"text"}]},{"type":"paragraph","content":[{"text":"Leyó noticias en una emisora en español de Nueva York y pasó por casi todo el dial dominicano, hasta quedar como director del departamento de locutores y coordinador de programación de La Voz Dominicana, y más tarde dirigir otras dos emisoras. Luego se pasó a la televisión y mantuvo un programa con su propio nombre en tres canales distintos, uno de ellos fundado por él.","type":"text"}]},{"type":"paragraph","content":[{"text":"Esa doble carrera importa para lo que vino después. Un cantante que además maneja un micrófono y una programación puede poner un repertorio al aire, y eso hizo.","type":"text"}]},{"type":"paragraph","content":[{"text":"La criolla","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"La criolla es la canción romántica dominicana del siglo diecinueve, la música de trovadores como Raudo Saldaña y Antonio Mesa, y a mediados del veinte era más o menos una pieza de museo. Grabó Cartas y Lágrimas, Aquel Beso, Carmencita y Duvergé, y siguió cantándolas cuando nada en el mercado premiaba hacerlo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Trabajó además como investigador y como escritor, cosa rara en un intérprete, y por eso el rescate cuajó. Estaba defendiendo una tesis sobre qué cosas incluye la música dominicana —el merengue y el bolero, sí, pero también la criolla, el son y los palos— y Juan Luis Guerra le dedicó el año pasado un texto largo a esa tesis.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lo más raro de su discografía va aquí también: un dúo con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ec0423fc-fe53-42e9-8d0f-f2ae902512d3","displayText":"Eduardo Brito","occurrenceId":"9d3cb12d-d490-46ce-a021-93fa43493b0b"}},{"text":". Brito murió en 1946, así que se armó por medios técnicos y no cantando juntos, y es exactamente el gesto de alguien que cree que el repertorio del diecinueve sigue siendo material vivo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Festivales y lo demás","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Representó al país en el festival OTI de la canción en España en 1972 con Siempre Habrá Una Sonrisa En La Luna, y quedó segundo en ese mismo festival en 1977 con Al Nacer Cada Enero. Ha cantado en el Carnegie Hall y salió en los grandes programas de variedades en español de la época, en Chile, en España y en el show mexicano que grabó una edición en La Romana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Su repertorio atraviesa la buena canción dominicana del período. Grabó Una Primavera Para El Mundo, sobre un poema de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c1575281-d275-4f34-a721-9f02736132d2","displayText":"René del Risco Bermúdez","occurrenceId":"3e2c1099-71eb-4179-a28e-a94cf38a90be"}},{"text":", y Por Amor, de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ba42e200-51b0-437b-99ac-1daf39ade337","displayText":"Rafael Solano","occurrenceId":"3078b063-14fd-45cd-a2d5-73b6cd865ce7"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"El Ayuntamiento del Distrito Nacional lo declaró munícipe distinguido, y más tarde fue escogido para la reserva musical del país. Sigue trabajando, sigue dando entrevistas en su casa y sigue defendiendo lo mismo sobre la criolla.","type":"text"}]}]}'::jsonb WHERE id = '28d383a1-f021-49e8-9d22-5e23f255d8da';
--   rafael-solano [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Rafael Leónidas Solano Sánchez is a Dominican composer, pianist, conductor and writer. He wrote Por Amor, which has gone further into the world than any other Dominican song, and he built the television programmes through which two generations of Dominican singers were first heard.","type":"text"}]},{"type":"paragraph","content":[{"text":"Puerto Plata","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born in Puerto Plata in 1931 and was treated as a prodigy by eleven, playing at the theatrical evenings his town put on. He came to the piano by way of the violin, the cello and the harmonium of the parish church, and in 1950 moved to the capital and enrolled at the National Conservatory.","type":"text"}]},{"type":"paragraph","content":[{"text":"He finished the whole course and then turned away from the concert career it pointed to, joining La Voz Dominicana, the country’s first television channel. He became one of its musical directors, working beside Italian, Cuban, Mexican and Argentine musicians who taught him orchestral arranging in practice. He later went to New York for private lessons with the American composer Hall Overton and study at the New School.","type":"text"}]},{"type":"paragraph","content":[{"text":"La Hora del Moro","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Back in Santo Domingo he became a television producer, and in 1959 put La Hora del Moro on the air. Until then singing on Dominican television meant La Voz Dominicana, the station founded by the dictator’s brother; the new Sunday programme opened a second door.","type":"text"}]},{"type":"paragraph","content":[{"text":"The voices that came through it include ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bdd072a-e0d4-472f-9579-ba9499ac4005","displayText":"Aníbal de Peña","occurrenceId":"b57d54ed-bfde-4101-8b1c-e8f0a066cbb5"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1131dfe6-f404-44b4-8d0d-f8120dc6f71a","displayText":"Fernando Casado","occurrenceId":"655ebf40-8995-4087-a1f2-159b061343c3"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"19124a2a-a49c-435e-989e-049b5dc3726c","displayText":"Niní Cáffaro","occurrenceId":"9eb83edc-cb69-4abf-bc18-66f42b50d808"}},{"text":", Horacio Pichardo, Arístides Incháustegui, Julio César Defilló, Luchy Vicioso, José Lacay and Los Olmeños. With Nobel Alfonso he later remade the format as a daily show and renamed it El Show del Mediodía, which is still on the air in Santo Domingo.","type":"text"}]},{"type":"paragraph","content":[{"text":"He also created the Festival de la Voz, a talent competition that produced ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"2307bdfa-70fc-417e-8227-1050eb2ec5e0"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"e57179c2-306d-4dcc-8b16-4e82f0f1fabd"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"4aa61dc5-6cf4-4be6-a0bf-5f244a5eb3d0"}},{"text":", Frank Valdez, Manny Oliva and Fausto Guillén. With ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"d100bc80-a9ae-48b9-9cab-48b6acf901d3"}},{"text":" he produced Letra y Música, a nightly programme of music and opinion, and later Solano en Domingo and Solano Invita.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por Amor","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Por Amor won the first Dominican Song Festival sung by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"19124a2a-a49c-435e-989e-049b5dc3726c","displayText":"Niní Cáffaro","occurrenceId":"064e2cbf-0e5a-436c-9e99-7be005e40b1e"}},{"text":". It has since been translated into several languages and recorded by Marco Antonio Muñiz, Tito Rodríguez, Jon Secada, Vikki Carr, the Mariachi Vargas and Plácido Domingo, which makes it the most widely travelled song the country has produced.","type":"text"}]},{"type":"paragraph","content":[{"text":"The rest of the catalogue runs past a hundred pieces. En la Oscuridad went out in the voice of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1131dfe6-f404-44b4-8d0d-f8120dc6f71a","displayText":"Fernando Casado","occurrenceId":"d54da193-5695-4a4c-9429-21771112471b"}},{"text":" and later in those of Muñiz and Tito Rodríguez; En Ruinas was recorded by Felipe Pirela, Quiero Verte by Vicentico Valdés, Yo Soy Tu Enamorado again by Tito Rodríguez. Cada Vez Más, Confundidos, Mi Amor por Ti, Confesión de Amor, Perdidamente Enamorado, El Sonido de Tu Voz and Magia belong to the same body of work.","type":"text"}]},{"type":"paragraph","content":[{"text":"He set the words of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c1575281-d275-4f34-a721-9f02736132d2","displayText":"René del Risco Bermúdez","occurrenceId":"c35b9e3b-f86a-4576-ac1d-c84898d6b113"}},{"text":" for Una Primavera para el Mundo, and the lyrics of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"0d18a025-56d8-4899-adf5-b08117b1440d"}},{"text":" for Pensándolo Bien.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mangulina and Carnegie Hall","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He did not stay inside the bolero. Como Juan, Fandango, Güira y Tambora and Mocanita are folk pieces, and Dominicanita and Pensándolo Bien are bolemengues, all of them recorded in his own voice with his orchestra behind him. He made an album called A Bailar la Mangulina in 1970.","type":"text"}]},{"type":"paragraph","content":[{"text":"The instrumental records carried him abroad. Amorama, released in 1969, was recorded at Carnegie Hall.","type":"text"}]},{"type":"paragraph","content":[{"text":"The writing","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His column Solanismos ran in Listín Diario from 1975. He published Letra y Música in 1992, which he described in its prologue as autobiographical accounts of a Dominican musician rather than an autobiography, and in 2003 wrote El merengue, música y baile de la República Dominicana with the musicologist Catana Pérez de Cuello. That book won the national book fair prize in 2005. Música y Pensamiento followed in 2016.","type":"text"}]},{"type":"paragraph","content":[{"text":"The honours","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He served as Dominican ambassador and delegate to UNESCO in Paris between 1982 and 1986, and holds the Order of Merit of Duarte, Sánchez and Mella. He received the Gran Dorado in 1976 and El Soberano in 2005, the two highest awards in Dominican popular music, and in 2016 the Latin Recording Academy gave him its Musical Excellence Award.","type":"text"}]}]}'::jsonb WHERE id = '0764dbbd-ecfe-412c-90ac-6069af91d86f';
--   rafael-solano [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Rafael Leónidas Solano Sánchez es un compositor, pianista, director de orquesta y escritor dominicano. Escribió Por Amor, que ha llegado más lejos en el mundo que ninguna otra canción dominicana, y armó los programas de televisión por los que se oyó por primera vez a dos generaciones de cantantes del país.","type":"text"}]},{"type":"paragraph","content":[{"text":"Puerto Plata","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació en Puerto Plata en 1931 y a los once años ya lo trataban de niño prodigio, presentándolo en las funciones teatrales de su pueblo. Llegó al piano pasando por el violín, el chelo y el armonio de la iglesia parroquial, y en 1950 se mudó a la capital y entró al Conservatorio Nacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terminó todos los cursos y entonces se desvió de la carrera de concierto a la que apuntaban, entrando a La Voz Dominicana, el primer canal de televisión del país. Llegó a ser uno de sus directores musicales, trabajando al lado de músicos italianos, cubanos, mexicanos y argentinos que le enseñaron arreglo orquestal en la práctica. Después se fue a Nueva York a tomar clases particulares con el compositor estadounidense Hall Overton y a estudiar en la New School.","type":"text"}]},{"type":"paragraph","content":[{"text":"La Hora del Moro","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"De vuelta en Santo Domingo se hizo productor de televisión, y en 1959 puso al aire La Hora del Moro. Hasta entonces cantar en la televisión dominicana quería decir La Voz Dominicana, la emisora fundada por el hermano del dictador; aquel programa dominical abrió una segunda puerta.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por ahí salieron ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bdd072a-e0d4-472f-9579-ba9499ac4005","displayText":"Aníbal de Peña","occurrenceId":"7144be02-ff86-41ec-bbe4-6165c77ca244"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1131dfe6-f404-44b4-8d0d-f8120dc6f71a","displayText":"Fernando Casado","occurrenceId":"1557da73-af0b-4e7b-83bb-d70070cf8f5e"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"19124a2a-a49c-435e-989e-049b5dc3726c","displayText":"Niní Cáffaro","occurrenceId":"dca6522b-7045-4a37-94cf-4cba869a6b92"}},{"text":", Horacio Pichardo, Arístides Incháustegui, Julio César Defilló, Luchy Vicioso, José Lacay y Los Olmeños. Con Nobel Alfonso rehízo después el formato en diario y lo rebautizó El Show del Mediodía, que sigue al aire en Santo Domingo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Creó además el Festival de la Voz, un concurso de donde salieron ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"cd335b4d-0884-4c22-b93d-b175b472bb4a"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"f743d299-12c6-4bfa-9040-bf2c2dcd29ee"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"355283d6-e730-49ae-b1f8-e6a805779188"}},{"text":", Frank Valdez, Manny Oliva y Fausto Guillén. Con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"f05b25d6-7b94-4977-8a37-68d1971209da"}},{"text":" produjo Letra y Música, programa nocturno diario de música y opinión, y más tarde Solano en Domingo y Solano Invita.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por Amor","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Por Amor ganó el I Festival de la Canción Dominicana en la voz de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"19124a2a-a49c-435e-989e-049b5dc3726c","displayText":"Niní Cáffaro","occurrenceId":"4707bb59-5548-47f1-ab10-8d7d77906a47"}},{"text":". Desde entonces se ha traducido a varios idiomas y la han grabado Marco Antonio Muñiz, Tito Rodríguez, Jon Secada, Vikki Carr, el Mariachi Vargas y Plácido Domingo, lo que la convierte en la canción que más ha viajado de cuantas ha producido el país.","type":"text"}]},{"type":"paragraph","content":[{"text":"El resto del catálogo pasa del centenar de piezas. En la Oscuridad salió en la voz de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"1131dfe6-f404-44b4-8d0d-f8120dc6f71a","displayText":"Fernando Casado","occurrenceId":"3d167cbd-8e55-4719-8809-9c37d5aba653"}},{"text":" y después en las de Muñiz y Tito Rodríguez; En Ruinas la grabó Felipe Pirela, Quiero Verte Vicentico Valdés, y Yo Soy Tu Enamorado otra vez Tito Rodríguez. Cada Vez Más, Confundidos, Mi Amor por Ti, Confesión de Amor, Perdidamente Enamorado, El Sonido de Tu Voz y Magia pertenecen al mismo cuerpo de obra.","type":"text"}]},{"type":"paragraph","content":[{"text":"Le puso música a los versos de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c1575281-d275-4f34-a721-9f02736132d2","displayText":"René del Risco Bermúdez","occurrenceId":"e8e559b6-cc59-4307-aee7-2cf37258bbbe"}},{"text":" en Una Primavera para el Mundo, y a la letra de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"2c22a1c7-472e-4570-9488-721096014df2"}},{"text":" en Pensándolo Bien.","type":"text"}]},{"type":"paragraph","content":[{"text":"La mangulina y el Carnegie Hall","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"No se quedó dentro del bolero. Como Juan, Fandango, Güira y Tambora y Mocanita son piezas folclóricas, y Dominicanita y Pensándolo Bien son bolemengues, todas grabadas en su propia voz y con su orquesta detrás. En 1970 hizo un disco titulado A Bailar la Mangulina.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los discos instrumentales lo sacaron del país. Amorama, publicado en 1969, se grabó en el Carnegie Hall.","type":"text"}]},{"type":"paragraph","content":[{"text":"La escritura","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su columna Solanismos salía en el Listín Diario desde 1975. Publicó Letra y Música en 1992, que él mismo describe en el prólogo como relatos autobiográficos de un músico dominicano y no como una autobiografía, y en 2003 escribió El merengue, música y baile de la República Dominicana junto a la musicóloga Catana Pérez de Cuello. Ese libro ganó el Premio Nacional Feria del Libro en 2005. Música y Pensamiento vino en 2016.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los reconocimientos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Fue embajador y delegado dominicano ante la Unesco en París entre 1982 y 1986, y tiene la Orden al Mérito de Duarte, Sánchez y Mella. Recibió El Gran Dorado en 1976 y El Soberano en 2005, los dos máximos galardones de la música popular dominicana, y en 2016 la Academia Latina de la Grabación le entregó su Premio a la Excelencia Musical.","type":"text"}]}]}'::jsonb WHERE id = 'd035d10d-e146-4aad-a73c-70bbb674acb6';

-- los-jovenes-del-amargue: "Los Jovenes Del Amargue" -> "Los Jóvenes del Amargue"
UPDATE artists SET name = 'Los Jóvenes del Amargue', stage_name = 'Los Jóvenes del Amargue', sort_name = 'Los Jóvenes del Amargue' WHERE slug = 'los-jovenes-del-amargue';
--   el-chaval-de-la-bachata [en]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Linar de Jesús Espinal Núñez, who performs as El Chaval de la Bachata, is a Dominican bachata singer, composer, guitarist and producer. He has been recording since 1994, took bachata of the year at the Casandra awards in 2009 and bachata singer of the year at the Soberano in 2026, and has spent most of the intervening years on the nomination lists.","type":"text"}]},{"type":"paragraph","content":[{"text":"The accordion and the guitar","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born on 4 December 1978 in Juncalito, a district of the municipality of Jánico, in the province of Santiago. The first instrument he set out to play was the accordion; he traded it for a guitar at seven, by which time the family had moved to the city of Santiago, where what caught him were the bachatas of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2b644026-3e99-4229-a729-003f04103f30","displayText":"Blas Durán","occurrenceId":"ddc017d1-e281-4801-928c-045d923b2c28"}},{"text":". As a boy he collected scrap metal to sell at the market and bring money home while he was still at school.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Infantiles del Amargue","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"At thirteen he met Juan Tavárez, who ran a bachata group with his eight-year-old son Joel on guitar. Together they formed Los Infantiles del Amargue, with Espinal as lead voice and second guitar, and recorded Si te vas for the businessman Nepo Núñez. The group went on performing under a second name, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ad2932a5-9ca5-4e96-88a2-d2bdf42440b0","displayText":"Los Jóvenes del Amargue","occurrenceId":"4c56592c-4de5-48aa-baf5-26bda53146c5"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Sentimiento Único","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1997, after three years with the group, he went out alone under the name El Chaval de la Bachata. Sentimiento Único came out that year on Nepo Núñez Records, and Cuando el amor se va became a standard of the genre; the record earned him a gold certification. Enfermo de amor, Para toda la vida, Para siempre, Volveré and Ayer y hoy followed on the same label.","type":"text"}]},{"type":"paragraph","content":[{"text":"Estoy perdido","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Devuélveme todo, from 2004, carried a tribute to ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"78e7f0da-3ab6-43d9-a0c2-b17762e7144c"}},{"text":" and the song Estoy perdido, which worked at home and abroad and was nominated for bachata of the year at the Casandra awards. He remade it in 2021 with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a57b4811-f39b-438b-ab4b-01c6775f678b","displayText":"La Ross María","occurrenceId":"7c2ceb51-d2f9-4ebc-8c0d-4f25177d0c30"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Donde están esos amigos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Ya me cansé, in 2007, contained Donde están esos amigos and gave him his first entry on a Billboard chart, arriving at number ten on Tropical Albums. Two years later he was up for three Casandra awards at once — bachata singer of the year, songwriter of the year and bachata of the year — and won the last of them with that song, which was also nominated at the Billboard Latin Music Awards.","type":"text"}]},{"type":"paragraph","content":[{"text":"The albums kept coming: Lo que me pidas, Por el maldito dinero, Sincrodestino, whose single No soy tu marido was nominated in 2017, and Mil historias. In 2014 he recorded Tres semanas, written by the Mexican Marco Antonio Solís.","type":"text"}]},{"type":"paragraph","content":[{"text":"Canalla","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He sang Canalla with Romeo Santos on Utopía, and in 2019 appeared with him at the MetLife Stadium in New York in front of more than eighty thousand people. He has also recorded with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0760875d-6b6f-4a48-8aed-6e57934d1baa","displayText":"Luis Vargas","occurrenceId":"91852e19-bc56-4e81-8469-0e2398e60088"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"31915623-3206-4052-b13a-2170226671b9","displayText":"Leonardo Paniagua","occurrenceId":"168aeeb7-ee41-417f-a307-1bb34046406f"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6302aca6-2203-456f-ad96-6bd2f26ee9b3","displayText":"Luis Miguel del Amargue","occurrenceId":"2b70a722-c0e2-458d-ad0a-21e8544cf5b7"}},{"text":", and with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"3c84afd9-8991-4597-b793-9f5c3f91eadc"}},{"text":" on the four-volume record that closed that singer’s career.","type":"text"}]},{"type":"paragraph","content":[{"text":"Twenty-five years","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He marked twenty-five years in music in October 2022 with a concert at the United Palace in New York that sold out three weeks ahead, alongside ","type":"text"},{"type":"artistReference","attrs":{"artistId":"96e69c00-dbb0-4cb4-ab48-ea46be9c4591","displayText":"Raulín Rodríguez","occurrenceId":"9cdecf34-393e-4939-975e-442a02972f86"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3dd83e6b-2058-4d04-ac68-38e11d9348a9","displayText":"Frank Reyes","occurrenceId":"ac60f8d3-b92e-4d75-bbbf-56e36a1073e1"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6321da6c-e2d5-490a-a4e8-416bbee81edf","displayText":"Don Miguelo","occurrenceId":"39e8a1f7-3efa-42ce-820c-c0e4b8f2c526"}},{"text":". The following year he released Alayah #15, a set of more than twenty songs including a vallenato tribute to the Colombian Diomedes Díaz and Contrato de amantes, written for him by Romeo Santos.","type":"text"}]},{"type":"paragraph","content":[{"text":"In March 2026, at the forty-first Premios Soberano, he was named bachata singer of the year.","type":"text"}]}]}'::jsonb WHERE id = 'a2bb0eda-dde5-4faf-aced-d7405b998fcf';
--   el-chaval-de-la-bachata [es]: 1 referencia(s)
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Linar de Jesús Espinal Núñez, que se presenta como El Chaval de la Bachata, es un cantante, compositor, guitarrista y productor dominicano de bachata. Graba desde 1994, se llevó la bachata del año en los Casandra de 2009 y el bachatero del año en los Soberano de 2026, y ha pasado buena parte de los años intermedios en las listas de nominados.","type":"text"}]},{"type":"paragraph","content":[{"text":"El acordeón y la guitarra","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nació el 4 de diciembre de 1978 en Juncalito, distrito del municipio de Jánico, provincia Santiago. El primer instrumento que se propuso tocar fue el acordeón; lo cambió por la guitarra a los siete años, ya con la familia en la ciudad de Santiago, donde lo engancharon las bachatas de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2b644026-3e99-4229-a729-003f04103f30","displayText":"Blas Durán","occurrenceId":"55799cd3-14c9-411e-98d5-28e4379f4c24"}},{"text":". De niño recogía metales para venderlos en el mercado y aportar en su casa mientras estudiaba.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Infantiles del Amargue","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A los trece conoció a Juan Tavárez, que llevaba un grupo de bachata con su hijo Joel, de ocho años, en la guitarra. Con ellos formó Los Infantiles del Amargue, donde Espinal era voz principal y segunda guitarra, y grabó Si te vas para el empresario Nepo Núñez. La agrupación siguió tocando con un segundo nombre, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ad2932a5-9ca5-4e96-88a2-d2bdf42440b0","displayText":"Los Jóvenes del Amargue","occurrenceId":"ff21de80-dbc3-424a-8264-c926dcba3398"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Sentimiento Único","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1997, tras tres años con el grupo, salió en solitario con el nombre de El Chaval de la Bachata. Sentimiento Único se publicó ese año bajo el sello Nepo Nuñez Records, y Cuando el amor se va se volvió un clásico del género; el disco obtuvo certificación de oro. Después vinieron Enfermo de amor, Para toda la vida, Para siempre, Volveré y Ayer y hoy, todos con el mismo sello.","type":"text"}]},{"type":"paragraph","content":[{"text":"Estoy perdido","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Devuélveme todo, de 2004, traía un homenaje a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"68b45893-f56c-4c5a-aa1b-ffa1a73697b7"}},{"text":" y la canción Estoy perdido, que funcionó dentro y fuera del país y fue nominada a bachata del año en los Casandra. La rehízo en 2021 con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a57b4811-f39b-438b-ab4b-01c6775f678b","displayText":"La Ross María","occurrenceId":"af25e720-1f58-4367-adfe-5414274eb917"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Donde están esos amigos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Ya me cansé, de 2007, contenía Donde están esos amigos y le dio su primera entrada en una lista de Billboard, en el décimo puesto de Tropical Albums. Dos años después optaba a tres Casandra a la vez —bachatero del año, compositor del año y bachata del año— y ganó el último con esa canción, nominada además en los Premios Billboard de la Música Latina.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los discos siguieron: Lo que me pidas, Por el maldito dinero, Sincrodestino, cuyo sencillo No soy tu marido fue nominado en 2017, y Mil historias. En 2014 grabó Tres semanas, escrita por el mexicano Marco Antonio Solís.","type":"text"}]},{"type":"paragraph","content":[{"text":"Canalla","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cantó Canalla con Romeo Santos en Utopía, y en 2019 se presentó con él en el MetLife Stadium de Nueva York ante más de ochenta mil personas. Ha grabado además con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0760875d-6b6f-4a48-8aed-6e57934d1baa","displayText":"Luis Vargas","occurrenceId":"60ec8233-24ed-4830-a72f-285811b4f5cb"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"31915623-3206-4052-b13a-2170226671b9","displayText":"Leonardo Paniagua","occurrenceId":"153b78bf-d328-45e3-a064-66ca3e439d4a"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6302aca6-2203-456f-ad96-6bd2f26ee9b3","displayText":"Luis Miguel del Amargue","occurrenceId":"456ad5eb-c0f4-4bba-8faa-273e7e1598ae"}},{"text":", y con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"586e4faf-cd57-455e-b751-a38b6151c2fe"}},{"text":" en el disco de cuatro volúmenes con el que aquel cerró su carrera.","type":"text"}]},{"type":"paragraph","content":[{"text":"Veinticinco años","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Celebró sus veinticinco años en la música en octubre de 2022 con un concierto en el United Palace de Nueva York que agotó las entradas tres semanas antes, acompañado por ","type":"text"},{"type":"artistReference","attrs":{"artistId":"96e69c00-dbb0-4cb4-ab48-ea46be9c4591","displayText":"Raulín Rodríguez","occurrenceId":"e16f5b34-7876-4dd5-a0bc-3f29ee9a9897"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3dd83e6b-2058-4d04-ac68-38e11d9348a9","displayText":"Frank Reyes","occurrenceId":"d4feac78-27cc-4846-8d80-efc906a5547f"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6321da6c-e2d5-490a-a4e8-416bbee81edf","displayText":"Don Miguelo","occurrenceId":"b5c59b73-e110-41d0-b2af-06d15a6714c5"}},{"text":". Al año siguiente publicó Alayah #15, más de veinte canciones entre las que hay un homenaje en vallenato al colombiano Diomedes Díaz y Contrato de amantes, que le escribió Romeo Santos.","type":"text"}]},{"type":"paragraph","content":[{"text":"En marzo de 2026, en la 41.ª entrega de los Premios Soberano, fue nombrado bachatero del año.","type":"text"}]}]}'::jsonb WHERE id = 'd9bb80a0-7616-4993-a465-2813a03fac26';

